#include <webcpp/cobalt/channel.hpp>
#include <webcpp/cobalt/main.hpp>
#include <webcpp/cobalt/promise.hpp>

#include <iostream>

namespace cobalt = webcpp::cobalt;

// tag::channel_example[]
cobalt::promise<void> producer(cobalt::channel<int>& chan) {
    for (int i = 0; i < 4; i++)
        co_await chan.write(i);

    chan.close();
}

cobalt::main co_main(int argc, char* argv[]) {
    cobalt::channel<int> c;

    auto p = producer(c);
    while (c.is_open())
        std::cout << co_await c.read() << std::endl;

    co_await p;
    co_return 0;
}

// end::channel_example[]
